  $('#undo-ink').onclick=()=>{commitSignature();if(history.length)ctx.putImageData(history.pop(),0,0);};$('#add-text').onclick=()=>{const text=prompt('النص أو التاريخ الذي تريد إضافته:',new Date().toLocaleDateString('ar'));if(!text)return;commitSignature();checkpoint();ctx.fillStyle=$('#pen-color').value;ctx.font=`${Math.max(24,canvas.width*.035)}px Tahoma, Arial`;ctx.textAlign='right';ctx.fillText(text,canvas.width*.95,canvas.height*.93,canvas.width*.9);};
