 $('#save-signature').onclick=async()=>{if(!inkBounds)return toast('ارسم التوقيع بالقلم أولاً');const b=inkBounds,c=Core.makeCanvas(b.x1-b.x0,b.y1-b.y0);c.getContext('2d').drawImage(ink,b.x0,b.y0,c.width,c.height,0,0,c.width,c.height);await setUserPreference('signature',await Core.blobData(await Core.toBlob(c,'image/png')));toast('تم حفظ التوقيع لإعادة الاستخدام');};
